using System.IO;
using System.Linq;
using System.Xml;
using NUnit.Framework;

namespace Enterprise.Customs.GB.ICS.Messaging.Testing
{
	sealed class HMRCmarkAuthenticatorTest : TransactionedTestCase
	{
		[DatCapabilityRequirement("SOURCE_CODE")]
		public void TestSignOutgoingSOAP()
		{
			// Provide a SOAP message generated by the to-be-designed Message Sender
			// Check the resulting SOAP has the expected Signature tag in the Header

			var outgoingMessage = File.ReadAllText(Path.Combine(TestCase.BaseSourcePath, TestFilesPath, "ie818_submission.xml"));

			var outgoingXml = new XmlDocument();
			outgoingXml.LoadXml(outgoingMessage);
			var outgoingBodyNode = outgoingXml.SelectSingleNode("/*[local-name()='Envelope']/*[local-name()='Body']");
			var outgoingBody = outgoingBodyNode.OuterXml;

			var authenticator = new HMRCmarkAuthenticator();
			var signedMessage = authenticator.SignSoapMessage(outgoingMessage);

			var signedXML = new XmlDocument();
			signedXML.LoadXml(signedMessage);

			var securityToken = signedXML.SelectSingleNode("/*[local-name()='Envelope']/*[local-name()='Header']/*[local-name()='Security']/*[local-name()='BinarySecurityToken']");
			AssertEquals("tWL4cdhGrS/D7TdEMk+TvjTCESY=", securityToken.InnerText);

			var signedSoapBodyXml = signedXML.SelectSingleNode("/*[local-name()='Envelope']/*[local-name()='Body']").OuterXml;
			AssertEquals(signedSoapBodyXml, outgoingBody);
		}

		[DatCapabilityRequirement("SOURCE_CODE")]
		public void TestCanonicalizeAndCalculateSHA1()
		{
			var canonicalbody = File.ReadAllText(Path.Combine(TestCase.BaseSourcePath, TestFilesPath, "ie818_canonicalbody.xml"));
			var authenticator = new HMRCmarkAuthenticator();
			var sha = authenticator.CanonicalizeAndCalculateSHA1(canonicalbody);
			AssertEquals("tWL4cdhGrS/D7TdEMk+TvjTCESY=", sha);
		}

		public void TestCodeAliveAttrRemoved()
		{
			var type = typeof(HMRCmarkAuthenticator);
			AssertEquals(expected: false, actual: type.CustomAttributes.Any(attr => attr.AttributeType.FullName == "WTG.StaticAnalysis.Annotation.CodeAliveAttribute"));
		}

		const string TestFilesPath = @"Enterprise\Product\Operations\Customs\GB\Manifest\ICS.Test\TestFiles";
	}
}
